/// <summary>
/// GUPPricingAttribute of table <c>InventTableModule</c> field LineDisc.
/// </summary>
[GUPPricingMetadataDiscovery][GUPPricingAttributeSourceDiscovery(GUPPricingAttributeSource::Product, GUPPricingAttributeSourceLevel::Line)]
[GUPPricingAttributeFieldsDiscovery(fieldStr(InventTableModule, LineDisc))]
internal class GUPPricingAttributeInventTableModuleSalesLineDisc extends GUPPricingAttributeInventTableModuleSales implements GUPIPricingAttribute
{

}

Method.Source:
public str getName()
{
    return strFmt("%1 - %2", enum2Str(ModuleInventPurchSales::Sales), fieldPName(InventTableModule, LineDisc));
}

public Set getAllowedValuesWithDescription()
{
    var ret = new Set(Types::AnyType);

    InventTableModule   inventTableModule;       
    PriceDiscGroup      priceDiscGroup;
    InventTable         inventTable;

    while select LineDisc from inventTableModule
        join priceDiscGroup
        group by GroupId, Name, Module, Type
        where inventTableModule.LineDisc == priceDiscGroup.GroupId 
            && InventTablemodule.ModuleType == ModuleInventPurchSales::Sales
            && priceDiscGroup.Module  == ModuleInventCustVend::Invent 
            && priceDiscGroup.Type == PriceGroupType::LineDiscGroup                
        join ItemId from inventTable
        where inventTable.ItemId == inventTableModule.ItemId
    {
        GUPPricingAttributeAllowedValuesObject valueObject =
            new GUPPricingAttributeAllowedValuesObject(priceDiscGroup.GroupId, priceDiscGroup.Name);
        ret.add(valueObject);
    }
    return ret;
}
